import { getFunctions, httpsCallable } from 'firebase/functions'
import { useCallback, useEffect, useRef, useState } from 'react'

/**
 * Custom hook for session validation
 * Eliminates duplicated session validation logic across MappingApp, DoorknockingApp, EventCoordination
 * @param {Object} user - The current user object from usePermissions
 * @return {Object} - { isValidSession, isLoading, revalidate }
 */
function useSessionValidation(user) {
  const [isLoading, setIsLoading] = useState(true)
  const [isValidSession, setIsValidSession] = useState(false)
  const functionsRef = useRef(null)

  const validate = useCallback(async () => {
    if (!user?.uid) {
      setIsLoading(false)
      setIsValidSession(false)
      return
    }

    const sessionId = localStorage.getItem('sessionId')
    if (!sessionId) {
      setIsLoading(false)
      setIsValidSession(false)
      return
    }

    try {
      if (!functionsRef.current) {
        functionsRef.current = getFunctions()
      }
      const validateSessionFn = httpsCallable(functionsRef.current, 'validateSession')
      const result = await validateSessionFn({ sessionId })
      setIsValidSession(result.data?.isValid ?? false)
    } catch (error) {
      console.error('Session validation error:', error)
      setIsValidSession(false)
    } finally {
      setIsLoading(false)
    }
  }, [user?.uid])

  useEffect(() => {
    validate()
  }, [validate])

  return {
    isValidSession,
    isLoading,
    revalidate: validate,
  }
}

export default useSessionValidation
